import{fetchCohortJSON}from'./current-cohort-loader.js';import{onetQuestions,onetResponseOptions,onetInstrument,riasecNames}from'./onet-assessment.js';import{lifestyleChoices}from'./lifestyle-builder.js';import{hydrateCurrent092}from'./match-fit-092.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n!==null&&n!==''&&Number.isFinite(Number(n))?'$'+Math.round(Number(n)).toLocaleString():'Not recorded';let model,journey,questions={},stage=0,models=[],index,careerNames={},fieldNames={};
function response(a,q){if(a[6])return'Unknown · review hold';if(a[2]?.length)return a[2].map(id=>(typeof id==='number'?q.options[id]?.text:q.options.find(o=>o.id===id)?.text)||id).join(' · ');return({yes:'Would like to learn this',no:'Does not interest me',unsure:'Unsure',unfamiliar:'Needs to learn more'})[a[1]]||({none:'None appeal',unsure:'Unsure',unfamiliar:'Needs to learn more'})[a[3]]||(a[7]!=null?'Saved rating: '+a[7]:'Not recorded');}
function render(){for(const b of document.querySelectorAll('[data-stage]'))b.setAttribute('aria-current',Number(b.dataset.stage)===stage?'step':'false');const root=$('model-journey');if(stage===0){const b=journey.builder;root.innerHTML=`<div class="target">Lifestyle target: ${money(model.lifestyle.target)} / year</div><div class="question"><h2>Saved lifestyle choices</h2><p>Monthly spending: ${money(model.lifestyle.monthlySpending)}</p><dl class="journey-facts">${lifestyleChoices.map(c=>{const n=b?.complete?b.choices?.[c.id]:undefined,option=c.id==='home'&&b?.homeMode==='own'?c.ownOptions?.[n]:c.options[n];return`<div><dt>${h(c.question)}</dt><dd>${h(option?.title||'Custom budget / not recorded')}</dd></div>`;}).join('')}</dl><details><summary>Exact saved budget</summary><pre class="journey-json">${h(JSON.stringify(journey.lifestyle,null,2))}</pre></details><div class="actions"><button data-stage="1" class="primary">Interest profiler →</button></div></div>`;}else if(stage===1){root.innerHTML=`<div class="question"><h2>Interest profiler · ${journey.interest.filter(v=>Number.isInteger(v)&&v>=1&&v<=5).length} / 60 answered</h2><p>Recorded multiple-choice responses, in their original order.</p><div class="table-scroll"><table class="journey-answers"><thead><tr><th>Activity</th><th>Saved answer</th></tr></thead><tbody>${onetQuestions.map((q,i)=>`<tr><td>${i+1}. ${h(q.text)}</td><td><b>${h(onetResponseOptions.find(o=>o.value===journey.interest[i])?.label||'Not answered')}</b></td></tr>`).join('')}</tbody></table></div><p class="note">${h(onetInstrument.attribution)}</p><button data-stage="2" class="primary">Follow-up answers →</button></div>`;}else if(stage===2){const groups=new Map();for(const a of journey.answers){const q=questions[a[0]],label=q.kind==='field'?'Field: '+(fieldNames[q.scope]||q.scope):q.kind==='facet'?'Interest: '+q.scope:'Career: '+(careerNames[q.scope]||q.scope);groups.set(label,[...(groups.get(label)||[]),{a,q}]);}root.innerHTML=`<div class="question"><h2>${journey.answers.length} saved follow-up answers</h2><p>These models may have more saved checks than a short live student session. Unknowns remain unknown. Shared activities can appear under more than one profession.</p><label>Find a question<input id="question-search" type="search" placeholder="Activity or profession"></label><div id="answer-groups">${[...groups].map(([label,items])=>`<details class="journey-answer-group" data-questions="${h(items.map(({q})=>q.prompt+' '+q.scope).join(' ').toLowerCase())}"><summary>${h(label)} · ${items.length}</summary><ol>${items.map(({a,q})=>`<li><p>${h(q.prompt)}<br><b>${h(response(a,q))}</b><small>${h(a[4]==='student'?'Authored model answer':a[4]==='profile-inferred'?'Profile-based simulated answer':a[4]||'Saved answer')}</small>${a[6]?'<small>'+h(a[6])+'</small>':''}</p></li>`).join('')}</ol></details>`).join('')||'<p>No profession follow-ups were recorded.</p>'}</div><div class="actions"><button data-stage="3" class="primary">See professions →</button></div></div>`;const input=$('question-search');input.oninput=()=>{for(const el of root.querySelectorAll('[data-questions]'))el.hidden=!el.dataset.questions.includes(input.value.toLowerCase().trim());};}else{root.innerHTML=`<div class="actions"><h2>Current professions</h2><a href="/results-board.html?model=${encodeURIComponent(model.id)}">Open full results →</a></div><p>${model.supported.filter(o=>o.top).length} Top · ${model.supported.length} supported · ${model.candidates.length} to explore</p><iframe class="journey-results" title="${h(model.name)} current professions" src="/results-board.html?model=${encodeURIComponent(model.id)}&journey=1"></iframe>`;}}
async function open(id){const selected=models.find(r=>r.id===id);if(!selected)throw Error('Choose a model from the list.');model=selected;$('name').textContent=model.name;$('journey-model').value=id;const chunk=index.chunks.find(p=>p.ids.includes(id));if(!chunk)throw Error('Saved journey unavailable.');const[data,qs,templates]=await Promise.all([fetchCohortJSON('/developer/model-journeys-092/'+chunk.file),fetchCohortJSON('/developer/model-journeys-092/'+index.questions),fetchCohortJSON('/developer/model-journeys-092/'+index.answers)]);journey=data.rows.find(r=>r.id===id);journey={...journey,answers:journey.answers.map(([q,a])=>[q,...templates[a]])};questions=qs;stage=0;$('model-journey').removeAttribute('role');const u=new URL(location.href);u.searchParams.set('model',id);history.replaceState({},'',u);render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(b&&journey){stage=Number(b.dataset.stage);render();}});$('journey-model-form').onsubmit=e=>{e.preventDefault();open($('journey-model').value).catch(err=>$('model-journey').textContent=err.message);};
try{const[d,i]=await Promise.all([fetchCohortJSON('/developer/current-students-091.json.gz'),fetchCohortJSON('/developer/model-journeys-092/index.json')]);models=hydrateCurrent092(d);careerNames=Object.fromEntries(Object.values(d.catalog).map(o=>[o.id,o.title]));fieldNames=Object.fromEntries(d.fields.map(f=>[f.id,f.title]));index=i;$('journey-models').innerHTML=models.map(r=>`<option value="${h(r.id)}">${h(r.name)}</option>`).join('');await open(new URL(location.href).searchParams.get('model')||'scale056-0061');}catch(e){$('model-journey').textContent='Could not open the journey: '+e.message;}
